"use client"
import { useState, useEffect, useRef } from "react"
import { Bell, CheckCircle2, MessageSquare, ExternalLink } from "lucide-react"
import Link from "next/link"

export function resolveNotificationLink(n: { title?: string; message?: string; link?: string | null }): string {
  const text = ((n.title || "") + " " + (n.message || "")).toLowerCase()
  const rawMsg = (n.title || "") + " " + (n.message || "")

  // Helper to extract teacher name and topic from notification text (backward compatibility for old notifications)
  const extractTeacherAndTopic = () => {
    let teacherName = ""
    let topic = ""

    // Match patterns like: "Thầy/Cô Đặng Thị Thúy Nga vừa mở tiết...", "Cô Thúy Nga vừa có tiết...", "GV Nguyễn Văn A..."
    const matchTeacher = rawMsg.match(/(?:thầy\/cô|thay\/co|thầy|cô|gv)\s+([^,.(]+?)\s+vừa (?:mở|có|đăng ký)/i)
    if (matchTeacher && matchTeacher[1]) {
      teacherName = matchTeacher[1].trim()
    }

    // Match topic inside parentheses: "(Toán - Phép cộng có nhớ)" or "(Hình học 10)"
    const matchTopic = rawMsg.match(/\((?:[^(]*?-\s*)?([^)]+)\)/)
    if (matchTopic && matchTopic[1]) {
      topic = matchTopic[1].trim()
    }

    let query = ""
    if (teacherName) query += `&teacherName=${encodeURIComponent(teacherName)}`
    if (topic) query += `&topic=${encodeURIComponent(topic)}`
    return query
  }

  // If notification has a link
  if (n.link && n.link.trim() !== "") {
    let link = n.link.trim()

    // Normalize du-gio links
    if (link.startsWith("/teacher/du-gio")) {
      // If notification is about a new open slot for observation registration
      if (text.includes("mở tiết") || text.includes("tổ chuyên môn") || text.includes("đăng ký tham dự") || text.includes("đăng ký dự giờ") || text.includes("tiết dạy mới")) {
        // If old link pointed to register_request or generic du-gio
        if (link === "/teacher/du-gio" || link.includes("tab=register_request") || link === "/teacher/du-gio?tab=dang-ky") {
          const extractedQuery = extractTeacherAndTopic()
          return `/teacher/du-gio?tab=overview_slots${extractedQuery}&action=register`
        }
        // If link already has slotId or overview_slots, ensure action=register exists
        if (!link.includes("action=register")) {
          link += (link.includes("?") ? "&" : "?") + "action=register"
        }
        return link
      }

      // If notification is about an invitation, approval, or update on an existing observation
      if (text.includes("mời dự giờ") || text.includes("phê duyệt") || text.includes("chấp nhận") || text.includes("xác nhận tham gia") || text.includes("từ chối")) {
        // Direct to observation_list (Lịch dự giờ & Giờ dạy)
        if (!link.includes("tab=observation_list")) {
          return "/teacher/du-gio?tab=observation_list"
        }
        return link
      }

      // If notification is about evaluations, ratings, or feedback
      if (text.includes("đánh giá") || text.includes("phiếu dự giờ") || text.includes("góp ý") || text.includes("kết quả")) {
        if (!link.includes("tab=history")) {
          return "/teacher/du-gio?tab=history"
        }
        return link
      }
    }

    // Re-route coordination notifications sent from GVCN to GVBM to so-diem-nhan-xet
    if (
      link.startsWith("/teacher/diem-lop-chu-nhiem") &&
      (text.includes("phối hợp") || text.includes("chuyển tiếp ý kiến phhs") || (n.title && n.title.includes("[Ý kiến PHHS]")))
    ) {
      return link.replace("/teacher/diem-lop-chu-nhiem", "/teacher/so-diem-nhan-xet")
    }

    // Return custom link as-is if no special normalization matched
    return link
  }

  // If notification does NOT have a link, infer destination based on keywords
  if (text.includes("dự giờ") || text.includes("du gio") || text.includes("tiết dạy")) {
    if (text.includes("đánh giá") || text.includes("phiếu") || text.includes("kết quả")) {
      return "/teacher/du-gio?tab=history"
    }
    if (text.includes("mời") || text.includes("lịch dạy") || text.includes("tham gia")) {
      return "/teacher/du-gio?tab=observation_list"
    }
    if (text.includes("đề xuất") || text.includes("xác nhận") || text.includes("hết hạn") || text.includes("nhắc lịch")) {
      return "/teacher/du-gio?tab=my_schedule"
    }
    const extractedQuery = extractTeacherAndTopic()
    return `/teacher/du-gio?tab=overview_slots${extractedQuery}&action=register`
  }
  if (text.includes("khảo sát") || text.includes("nps") || text.includes("survey")) {
    return "/teacher/nps"
  }
  if (text.includes("cố vấn") || text.includes("check-in") || text.includes("mục tiêu") || text.includes("k12")) {
    return "/teacher/co-van-hoc-tap"
  }
  if (text.includes("hồ sơ") || text.includes("học sinh")) {
    return "/teacher/ho-so-hoc-sinh"
  }
  if (text.includes("công việc") || text.includes("nhiệm vụ") || text.includes("giao việc")) {
    return "/admin/tasks"
  }
  if (text.includes("xét duyệt") || text.includes("phê duyệt") || text.includes("học thử") || text.includes("tuyển sinh")) {
    return "/admin/xet-duyet-ket-qua"
  }
  if (text.includes("xếp lớp") || text.includes("chuyển lớp")) {
    return "/admin/student-transfers"
  }

  return "/teacher"
}

export function NotificationBell() {
  const [open, setOpen] = useState(false)
  const [notifs, setNotifs] = useState<any[]>([])
  const [unread, setUnread] = useState(0)
  const ref = useRef<HTMLDivElement>(null)

  const fetchNotifs = async () => {
    try {
      const res = await fetch("/api/notifications", { cache: "no-store" })
      if (res.ok) {
        const data = await res.json()
        if (Array.isArray(data.notifications)) {
          setNotifs(data.notifications)
          setUnread(typeof data.unreadCount === "number" ? data.unreadCount : data.notifications.filter((n: any) => !n.isRead).length)
        }
      }
    } catch (err) {
      console.error("Failed to fetch notifications:", err)
    }
  }

  const markAllAsRead = async () => {
    try {
      await fetch("/api/notifications", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({})
      })
      setUnread(0)
    } catch (err) {
      console.error("Failed to mark notifications read:", err)
    }
  }

  useEffect(() => {
    let timer: any = null

    const schedulePoll = () => {
      if (timer) clearInterval(timer)
      // Only poll when document is visible to save server resources & DB connections
      if (typeof document !== "undefined" && document.visibilityState === "visible") {
        fetchNotifs()
        timer = setInterval(fetchNotifs, 30000)
      }
    }

    schedulePoll()

    const handleVisibilityChange = () => {
      if (document.visibilityState === "visible") {
        schedulePoll()
      } else if (timer) {
        clearInterval(timer)
        timer = null
      }
    }

    const handleFocus = () => {
      fetchNotifs()
    }

    document.addEventListener("visibilitychange", handleVisibilityChange)
    window.addEventListener("focus", handleFocus)

    return () => {
      if (timer) clearInterval(timer)
      document.removeEventListener("visibilitychange", handleVisibilityChange)
      window.removeEventListener("focus", handleFocus)
    }
  }, [])

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (ref.current && !ref.current.contains(event.target as Node)) {
        setOpen(false)
      }
    }
    document.addEventListener("mousedown", handleClickOutside)
    return () => document.removeEventListener("mousedown", handleClickOutside)
  }, [ref])

  const handleOpen = () => {
    const nextState = !open
    setOpen(nextState)
    if (nextState && unread > 0) {
      markAllAsRead()
    }
  }

  return (
    <div className="relative inline-block text-left" ref={ref}>
      <button 
        onClick={handleOpen}
        title="Thông báo hệ thống"
        aria-label="Thông báo hệ thống"
        className="relative p-2 rounded-xl text-slate-600 hover:text-[#48BFE3] hover:bg-slate-100/80 transition-all focus:outline-none"
      >
        <div className="relative">
          <Bell className="size-5" />
          {unread > 0 && (
            <span className="absolute -top-1.5 -right-2 flex size-5 items-center justify-center rounded-full bg-rose-500 text-[10px] font-bold text-white shadow-md animate-pulse tabular-nums">
              {unread > 99 ? '99+' : unread}
            </span>
          )}
        </div>
      </button>

      {open && (
        <div className="absolute right-0 mt-2 w-80 sm:w-96 bg-white rounded-2xl shadow-2xl border border-slate-200 overflow-hidden z-50 animate-in fade-in slide-in-from-top-2 duration-150">
          <div className="p-4 bg-gradient-to-r from-teal-50 to-emerald-50 border-b border-teal-100/80 flex justify-between items-center">
            <h3 className="font-bold text-slate-800 text-sm flex items-center gap-2">
              <MessageSquare className="size-4 text-[#48BFE3]" />
              Thông báo hệ thống
            </h3>
            {unread > 0 && (
              <span className="bg-rose-100 text-rose-700 text-xs font-bold px-2 py-0.5 rounded-full tabular-nums">
                {unread} tin mới
              </span>
            )}
          </div>

          <div className="max-h-[380px] overflow-y-auto divide-y divide-slate-100">
            {notifs.length === 0 ? (
              <div className="p-8 text-center text-slate-400 font-medium">
                <Bell className="size-10 mx-auto text-slate-200 mb-2" />
                <p className="text-xs">Chưa có thông báo nào.</p>
              </div>
            ) : (
              notifs.map(n => {
                const targetLink = resolveNotificationLink(n)
                const cleanMessage = (n.message || "").replace(/\[Dự giờ\s*#[^\]]+\]\s*/gi, "")

                return (
                  <Link 
                    key={n.id} 
                    href={targetLink}
                    onClick={() => {
                      setOpen(false)
                      if (!n.isRead) {
                        fetch("/api/notifications", {
                          method: "POST",
                          headers: { "Content-Type": "application/json" },
                          body: JSON.stringify({ notificationId: n.id })
                        }).catch(() => {})
                        setUnread(prev => Math.max(0, prev - 1))
                      }
                    }}
                    className={"block p-3.5 hover:bg-teal-50/60 transition-colors cursor-pointer group " + (!n.isRead ? "bg-teal-50/30" : "")}
                  >
                    <div className="flex items-start justify-between gap-2 mb-1">
                      <h4 className="font-bold text-slate-800 text-xs flex items-center gap-1.5 leading-snug group-hover:text-[#00A19A] transition-colors">
                        <CheckCircle2 className="size-3.5 text-[#48BFE3] shrink-0 group-hover:text-[#00A19A]" />
                        {n.title}
                      </h4>
                      <span className="text-[10px] text-slate-400 font-normal whitespace-nowrap shrink-0 tabular-nums">
                        {new Date(n.createdAt).toLocaleDateString("vi-VN")}
                      </span>
                    </div>
                    <p className="text-slate-600 text-xs leading-relaxed pl-5 font-normal text-pretty">{cleanMessage}</p>
                    <div className="mt-1.5 pl-5 flex items-center text-[10px] text-[#48BFE3] group-hover:text-[#00A19A] font-semibold gap-1">
                      Xem chi tiết <ExternalLink className="size-2.5 group-hover:translate-x-0.5 transition-transform" />
                    </div>
                  </Link>
                )
              })
            )}
          </div>

          <div className="p-2.5 bg-slate-50 text-center border-t border-slate-100">
            <button 
              className="text-xs font-semibold text-slate-500 hover:text-slate-700 transition-colors" 
              onClick={() => setOpen(false)}
            >
              Đóng
            </button>
          </div>
        </div>
      )}
    </div>
  )
}
